import{_ as a,E as n,c as o,o as c,j as e,I as p,am as d,a as i}from"./chunks/framework.pKienSF_.js";const f=JSON.parse(`{"title":"Cursor 相关","description":"","frontmatter":{"head":[["script",{"charset":"UTF-8","id":"LA_COLLECT","src":"//sdk.51.la/js-sdk-pro.min.js"}],["script",{},"typeof LA !== 'undefined' && LA.init({\\"id\\":\\"3LNfUkScYzEz6k4D\\",\\"ck\\":\\"3LNfUkScYzEz6k4D\\",\\"hashMode\\":true})"]]},"headers":[],"relativePath":"efficiency/software/cursor.md","filePath":"efficiency/software/cursor.md","lastUpdated":1767175595000}`),l={name:"efficiency/software/cursor.md"},r=e("h1",{id:"cursor-相关",tabindex:"-1"},[i("Cursor 相关 "),e("a",{class:"header-anchor",href:"#cursor-相关","aria-label":'Permalink to "Cursor 相关"'},"​")],-1),t=d(`<p>在重度使用 <code>Cursor</code> 几个月后，我也算有了几点心得，下面就来详细说下</p><h2 id="一些使用心得" tabindex="-1">一些使用心得 <a class="header-anchor" href="#一些使用心得" aria-label="Permalink to &quot;一些使用心得&quot;">​</a></h2><h3 id="缩小变更范围-不要试图一次做太多" tabindex="-1">缩小变更范围，不要试图一次做太多 <a class="header-anchor" href="#缩小变更范围-不要试图一次做太多" aria-label="Permalink to &quot;缩小变更范围，不要试图一次做太多&quot;">​</a></h3><p>在使用 <code>AI</code> 编辑器 coding 过程中，我的建议是一个功能点一个功能点的去做，尽量让更改范围小些。这样不至于让 <code>AI</code> 写的代码变得越来越不可控，更小的更改范围也有助于我们更好的阅读、理解 <code>AI</code> 写的代码，毕竟，人才是写代码的主体。</p><h3 id="让-cursor-复述你的要求" tabindex="-1">让 cursor 复述你的要求 <a class="header-anchor" href="#让-cursor-复述你的要求" aria-label="Permalink to &quot;让 cursor 复述你的要求&quot;">​</a></h3><p>我们陈述的语言是有模糊性的，加上 <code>ai</code> 理解特定信息的局限性，以及 <code>ai</code> 生成内容的随机性，有些时候我们可能会遇到 <code>ai</code>”答非所问“的情况，这个时候别怪 <code>ai</code>，应该先看下自己的提问或描述是否清晰易懂，最好的方法就是让 <code>ai</code> 复述一遍你的需求，看 <code>ai</code> 是否充分理解了。</p><h3 id="善用图示提问" tabindex="-1">善用图示提问 <a class="header-anchor" href="#善用图示提问" aria-label="Permalink to &quot;善用图示提问&quot;">​</a></h3><p>如果你的需求是否很难用文字完全描述清楚，可以适当增加一些图示，这样能更好地帮助 <code>cursor</code> 去理解你的意图</p><h3 id="先-save-再-accept" tabindex="-1">先 save 再 accept <a class="header-anchor" href="#先-save-再-accept" aria-label="Permalink to &quot;先 save 再 accept&quot;">​</a></h3><p><code>Cursor</code> 写完代码后。可以不用那么着急着去点 accept all，因为你也不知道 <code>cursor</code> 每次生成的代码是不是正确的。更好的方法是先去验证下 Cusor 写的代码是否正确，让后再点击 accept all，当然如果你不小心点到了 accept all，也可以 <code>ctrl</code> + z 撤回。</p><h3 id="使用-ask-模式制定计划-使用-agent-模式实施计划" tabindex="-1">使用 Ask 模式制定计划，使用 Agent 模式实施计划 <a class="header-anchor" href="#使用-ask-模式制定计划-使用-agent-模式实施计划" aria-label="Permalink to &quot;使用 Ask 模式制定计划，使用 Agent 模式实施计划&quot;">​</a></h3><p>当前版本 <code>cursor</code> 有 <code>Ask</code> 、<code>Agent</code> 和 <code>Plan</code> 三种模式，我的方法是一般就是先用 <code>Ask</code> 模式与 <code>cursor</code> 沟通好需求的背景、目的、技术方案等，或者直接上传 <code>prd</code>，让它结合项目本身技术栈自己生成技术方案，等到形成相对成熟的方案后再放到 <code>Agent</code> 模式去执行，这样效率更高。<code>Plan</code> 模式我可能只会在大型功能开发、复杂重构和项目初始化时使用。</p><h3 id="经常创建新的对话" tabindex="-1">经常创建新的对话 <a class="header-anchor" href="#经常创建新的对话" aria-label="Permalink to &quot;经常创建新的对话&quot;">​</a></h3><p>每次完成一个新功能，最好新开对话，避免之前的上下文对后面的功能开发造成污染，这也是我之前踩过的一个坑</p><h3 id="上下文是准确性的基石" tabindex="-1">上下文是准确性的基石 <a class="header-anchor" href="#上下文是准确性的基石" aria-label="Permalink to &quot;上下文是准确性的基石&quot;">​</a></h3><p>用 ‘@’ 标记相关文件和使用网络链接可以显著提高代码建议的准确性</p><h3 id="复杂任务" tabindex="-1">复杂任务 <a class="header-anchor" href="#复杂任务" aria-label="Permalink to &quot;复杂任务&quot;">​</a></h3><ol><li>初始规划</li></ol><p>在一次对话中询问 <code>AI</code>：</p><p>“实现/解决 [问题] 的最佳方法是什么，分步骤详细说明？”</p><ol start="2"><li>第一步执行</li></ol><p>在同一对话中请求：</p><p>“给我一个完整的提示，详细说明第一步需要做什么”</p><p>将此提示粘贴到一个新的作曲家对话中</p><p>执行任务</p><p>要求对已完成的工作进行总结</p><ol start="3"><li>迭代进展</li></ol><p>返回到第一个对话并说明：</p><p>我已经完成了第一步，这是已完成工作的总结：{总结}。现在，请建议一个超级提示，用于第二步，我可以将其粘贴到一个新对话中，以获取需要完成的任务的指导。</p><ol start="4"><li>重复此过程</li></ol><p>用第二步的提示开始新对话</p><p>获取工作摘要</p><p>返回到原始对话</p><p>要求下一个步骤的提示</p><p>....</p><p>为每个步骤重复此过程。这可以发挥每个任务不同上下文的优势，避免一次性向 <code>LLM</code> 提供过多信息而造成混乱。</p><h3 id="处理大型代码库" tabindex="-1">处理大型代码库 <a class="header-anchor" href="#处理大型代码库" aria-label="Permalink to &quot;处理大型代码库&quot;">​</a></h3><p><a href="https://cursor.com/cn/docs/cookbook/large-codebases" target="_blank" rel="noreferrer">https://cursor.com/cn/docs/cookbook/large-codebases</a></p><p>缩小每次修改的范围，不要一次尝试做太多 尽量提供相关上下文 针对各自擅长的场景使用 <code>Chat</code>、<code>Inline Edit</code> 和 <code>Tab</code> 经常新建对话 用 <code>Ask</code> mode 做规划，用 <code>Agent</code> mode 来实现</p><h2 id="cursor-锁区问题" tabindex="-1">Cursor 锁区问题 <a class="header-anchor" href="#cursor-锁区问题" aria-label="Permalink to &quot;Cursor 锁区问题&quot;">​</a></h2><p>在 2025 年 的 7 月份，<code>Cursor</code> 中断了中国大陆用户的多个模型使用权。我们常使用几个模型比如 <code>Claude</code> 系列、<code>Gemini</code> 系列，在国内都无法使用。</p><p><a href="./images//cursorError.png"></a></p><h3 id="为什么会这样" tabindex="-1">为什么会这样 <a class="header-anchor" href="#为什么会这样" aria-label="Permalink to &quot;为什么会这样&quot;">​</a></h3><p>老实说，这次的锁区事件其实跟 <code>Cursor</code> 关系并不大，<code>Cursor</code> 作为一个 <code>AI</code>+<code>IDE</code> 编辑器，他自身其实并不开发模型，它是基于 <code>VSCode</code>​ 开源代码进行开发，再通过他的网络去调用如：<code>Claude</code>、<code>ChatGPT</code>、<code>Gemini</code> 等等这些模型，去使用的模型的能力。</p><p><code>Cursor</code> 也在他的公告里为自己喊冤：</p><p>Some models in <code>Cursor</code> may be unavailable in certain regions based on the terms and policies set by the model providers. We plan to re‑enable all models in any regions where they are supported. If our model partners allow access to your region, we plan to restore the affected models and update this page.</p><p>大概意思就是，这种限制并非 <code>Cursor</code> 故意为之，而是受到上游模型提供商政策变化的影响。类似的情况在 <code>AI</code> 行业并不罕见， <a href="https://docs.anthropic.com/en/api/supported-regions" target="_blank" rel="noreferrer"><code>Anthropic</code>（<code>Claude</code>）</a>、<a href="https://help.openai.com/zh-hans-cn/articles/5347006-openai-api-supported-countries-and-territories" target="_blank" rel="noreferrer"><code>OpenAI</code>（<code>GPT</code> / <code>o-series</code>）</a>、<a href="https://ai.google.dev/gemini-api/docs/available-regions?hl=zh-cn" target="_blank" rel="noreferrer">Google（<code>Gemini</code>）</a>等公司都有自己的不支持国家和地区。遗憾的是，中国大陆地区都在这三家公司的封禁名单中...即使是翻墙也不行</p><h3 id="怎么办" tabindex="-1">怎么办？ <a class="header-anchor" href="#怎么办" aria-label="Permalink to &quot;怎么办？&quot;">​</a></h3><p><code>Cursor</code> 官方给了几个方案</p><ol><li>勾选 <code>Auto</code> 选项，每次请求时自动选择可用模型。</li><li>如果你有能在当地正常使用的 <code>API</code> key，可以在 <code>Cursor</code> 中配置他，这样就可以绕过去限制。</li><li>申请按比例退款</li></ol><p>这三种方案其实都没有真正解决问题。官方相当于直接摆烂了，直接告诉国内用户：我也没办法了，您要不勉强用，要不直接退款吧。</p><p>真实情况也是如此——在 <code>Cursor</code> 的锁区事件后，大批量的中国用户放弃使用 <code>Cursor</code>，转而使用 <code>Trae</code>、<code>Windsurf</code> 等替代品。那段时间我也放弃 <code>Cursor</code> 去试用了下 <code>Trae</code>，但是使用了一段时间后，它着实令我有点失望，生成的代码常常驴头不对马嘴，智能型这方面还是不如 <code>Cursor</code>，于是我又回到了 <code>Cursor</code> 的怀抱...</p><p>锁区的问题还是得解决，民间社区中也有人逐渐摸索出了解决方案：</p><ol><li>修改网络类型：<code>ctrl</code> + shift + j 打开控制面板后，点击 Network，修改 <code>http</code> 模式，把默认的 <code>HTTP</code>/2 修改为 <code>HTTP</code>/1.1 <a href="./images/cursor-network.png"></a></li><li>在你的代理工具中，将 Tun Mode 打开 <a href="./images/clash-tun-mode.png"></a></li></ol><p>我实际测试了下，效果还行，常用的几个模型都能使用，就是链接有时候会中断，应该是我的代理不太稳定的问题。</p><p>社区中也有人使用 <code>Proxifier</code> 转发 api2.cursor.sh:443​ 来实现，这样既可以使用 http2 享受低延迟，也可以用上 <code>claude</code> 等模型，感兴趣的朋友可以去尝试下。</p><p>一顿操作下来也是够麻烦，使用体验还没有以前好。这此的锁区事件本质上还是受美国 <code>AI</code> 出口管制以及国家安全相关政策的影响，受中美技术竞争的影响，也不知道什么技术开发化才能真正到来，让锁区不再成为开发者的一个门槛。同时也望国内的相关公司支棱起来，能够开发出质量更好些、更好用的 <code>AI</code> 编辑器。</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><p>想要用好 <code>AI</code> 编辑器，rules 肯定是不能绕过去的，合理的 rules 能够提供明确的结构化指导来约束 <code>AI</code> 的行为，并且有效对抗“<code>AI</code>”幻觉，确保生成的代码符合项目标准。</p><p>当前 <code>Cursor</code> 有三种类型规则</p><ol><li>项目规则：存储在 .<code>cursor</code>/rules 中，受版本控制，作用范围限定在你的代码库内</li><li>用户规则：在整个 <code>Cursor</code> 环境中全局生效，由 <code>Agent</code>（<code>Chat</code>）使用</li><li>AGENTS.md：以 <code>Markdown</code> 格式编写的 <code>Agent</code> 指令，是 .<code>cursor</code>/rules 的简洁替代方案（一般来说很少使用）。</li></ol><p>旧版本的.cursorrules 规则文件已经被废弃，当前我还是更推荐写在 .<code>cursor</code>/rules 中的项目规则。</p><p>不同于面向全部项目生效的用户规则配置这么简单，项目规则需要根据不同类型的开发项目进行针对性撰写，尤其是其中的角色定位、技术栈选择、代码规范等要求，rules 要想写全写好，还真不是个简单事。为此，我的想法是——先找到一个通用的 rules 模板，然后 <code>AI</code> 编辑器中让 <code>AI</code> 分析当前项目的同事，结合我们之前给定的 rules 模板，生成一个符合我们当前项目要求的 rules。我当前使用 rules 模板如下：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>角色</span></span>
<span class="line"><span>你是一名精通  开发的高级工程师，拥有10年以上的  应用开发经验，熟悉  等开发工具和技术栈。你的任务是帮助用户设计和开发易用且易于维护的  应用。始终遵循最佳实践，并坚持干净代码和健壮架构的原则。</span></span>
<span class="line"><span>目标</span></span>
<span class="line"><span>你的目标是以用户容易理解的方式帮助他们完成  应用的设计和开发工作，确保应用功能完善、性能优异、用户体验良好。</span></span>
<span class="line"><span>要求</span></span>
<span class="line"><span>在理解用户需求、设计UI、编写代码、解决问题和项目迭代优化时，你应该始终遵循以下原则：</span></span>
<span class="line"><span>项目初始化</span></span>
<span class="line"><span></span></span>
<span class="line"><span>在项目开始时，首先仔细阅读项目目录下的 README.md文件并理解其内容，包括项目的目标、功能架构、技术栈和开发计划，确保对项目的整体架构和实现方式有清晰的认识；</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果还没有README.md文件，请主动创建一个，用于后续记录该应用的功能模块、页面结构、数据流、依赖库等信息。</span></span>
<span class="line"><span>需求理解</span></span>
<span class="line"><span></span></span>
<span class="line"><span>充分理解用户需求，站在用户角度思考，分析需求是否存在缺漏，并与用户讨论完善需求；</span></span>
<span class="line"><span></span></span>
<span class="line"><span>选择最简单的解决方案来满足用户需求，避免过度设计。</span></span>
<span class="line"><span>UI和样式设计</span></span>
<span class="line"><span></span></span>
<span class="line"><span>使用现代UI框架进行样式设计（例如*，这里可以根据不同开发项目仔细展开，比如使用哪些视觉规范或者UI框架，没有的话也可以不用过多展开）；</span></span>
<span class="line"><span></span></span>
<span class="line"><span>在不同平台上实现一致的设计和响应式模式</span></span>
<span class="line"><span>代码编写</span></span>
<span class="line"><span></span></span>
<span class="line"><span>技术选型：根据项目需求选择合适的技术栈（例如*，这里需要仔细展开，比如介绍某个技术栈用在什么地方，以及要遵循什么最佳实践）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>代码结构：强调代码的清晰性、模块化、可维护性，遵循最佳实践（如DRY原则、最小权限原则、响应式设计等）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>代码安全性：在编写代码时，始终考虑安全性，避免引入漏洞，确保用户输入的安全处理</span></span>
<span class="line"><span></span></span>
<span class="line"><span>性能优化：优化代码的性能，减少资源占用，提升加载速度，确保项目的高效运行</span></span>
<span class="line"><span></span></span>
<span class="line"><span>测试与文档：编写单元测试，确保代码的健壮性，并提供清晰的中文注释和文档，方便后续阅读和维护</span></span>
<span class="line"><span></span></span>
<span class="line"><span>问题解决</span></span>
<span class="line"><span></span></span>
<span class="line"><span>全面阅读相关代码，理解 * 应用的工作原理</span></span>
<span class="line"><span></span></span>
<span class="line"><span>根据用户的反馈分析问题的原因，提出解决问题的思路</span></span>
<span class="line"><span></span></span>
<span class="line"><span>确保每次代码变更不会破坏现有功能，且尽可能保持最小的改动</span></span>
<span class="line"><span>迭代优化</span></span>
<span class="line"><span></span></span>
<span class="line"><span>与用户保持密切沟通，根据反馈调整功能和设计，确保应用符合用户需求</span></span>
<span class="line"><span></span></span>
<span class="line"><span>在不确定需求时，主动询问用户以澄清需求或技术细节</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每次迭代都需要更新README.md文件，包括功能说明和优化建议</span></span>
<span class="line"><span>方法论</span></span>
<span class="line"><span></span></span>
<span class="line"><span>系统2思维：以分析严谨的方式解决问题。将需求分解为更小、可管理的部分，并在实施前仔细考虑每一步</span></span>
<span class="line"><span></span></span>
<span class="line"><span>思维树：评估多种可能的解决方案及其后果。使用结构化的方法探索不同的路径，并选择最优的解决方案</span></span>
<span class="line"><span></span></span>
<span class="line"><span>迭代改进：在最终确定代码之前，考虑改进、边缘情况和优化。通过潜在增强的迭代，确保最终解决方案是健壮的</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br><span class="line-number">54</span><br></div></div><h2 id="什么时候该选择什么模型" tabindex="-1">什么时候该选择什么模型 <a class="header-anchor" href="#什么时候该选择什么模型" aria-label="Permalink to &quot;什么时候该选择什么模型&quot;">​</a></h2><p>应该是根据不同场景使用不同的模型。当然，每个人的编码体验可能有所差别</p><p>使用 <code>Claude</code> sonnet 3.5 进行编码（是的，对于执行代码来说，它比 3.7 更好。） 使用 <code>GPT</code> o1/o3-mini-high 调试复杂错误。 使用 <code>Gemini</code> Flash 2.0 扫描整个代码库并更新文档</p><h2 id="经常使用的功能" tabindex="-1">经常使用的功能 <a class="header-anchor" href="#经常使用的功能" aria-label="Permalink to &quot;经常使用的功能&quot;">​</a></h2><h3 id="分析项目文件" tabindex="-1">分析项目文件 <a class="header-anchor" href="#分析项目文件" aria-label="Permalink to &quot;分析项目文件&quot;">​</a></h3><h3 id="截图生成组件" tabindex="-1">截图生成组件 <a class="header-anchor" href="#截图生成组件" aria-label="Permalink to &quot;截图生成组件&quot;">​</a></h3><p>除了一句话描述自己的需求，让 <code>Cursor</code> 生成组件代码之外，有时候我们可能会看到某个网站的某个组件设计的不错，想把这个组件的样式和逻辑复制到自己的项目中。</p><p>在 <code>Cursor</code> 中，只需要截图参考的组件，让它仿照着写出来就行了。</p><p>这比起以前去 Copy 别人网站的样式，通过审查元素查看 HTML 结构和 CSS 样式，效率高的不止一点半点。</p><h3 id="代码重构" tabindex="-1">代码重构 <a class="header-anchor" href="#代码重构" aria-label="Permalink to &quot;代码重构&quot;">​</a></h3><h3 id="多语言翻译" tabindex="-1">多语言翻译 <a class="header-anchor" href="#多语言翻译" aria-label="Permalink to &quot;多语言翻译&quot;">​</a></h3><p>我们做出海 <code>AI</code> 应用，面向全球用户，往往需要支持多语言。</p><p>使用 <code>NextJS</code> 框架做全栈开发，多语言方案用的是 <code>next-intl</code>，只需要在项目的 messages 目录下放置语言的 <code>json</code> 文件即可。</p><p>在使用 <code>Cursor</code> 之前，要支持多语言，我一般会先写好 en.json 的内容，再把 en.json 的内容复制到 <code>ChatGPT</code>，让它翻译成其他语言的 <code>json</code> 文件，比如 zh.json / ja.json 等，然后把翻译好的 <code>json</code> 文件都放置到 messages 目录下。</p><p>每次新增 / 修改 / 删除要支持多语言的内容，我需要先更新 en.json 的内容，再按照上面的流程更新其他语言文件的内容。效率非常的低！！！</p><p>现在使用 <code>Cursor</code>，我还是会先更新 en.json 的内容，然后去到其他语言文件中，按下 <code>Tab</code> 键，快速补全，<code>Cursor</code> 会自动填充翻译好的内容。</p><p>使用 <code>Cursor</code> 做多语言文件的翻译简直太友好了，效率有了十倍以上的提升</p><h2 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h2><h3 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p><code>MCP</code> 是一种开放协议，它标准化了应用程序向 <code>LLM</code> 提供上下文的方式。可以将 <code>MCP</code> 视为 <code>AI</code> 应用程序的 USB-C 端口。正如 USB-C 提供了一种将设备连接到各种外围设备和配件的标准化方式一样，<code>MCP</code> 提供了一种将 <code>AI</code> 模型连接到不同数据源和工具的标准化方式。（<code>MCP</code> 的全称是 Model Context Protocol，是一个开放协议，它使  <code>LLM</code>  应用与外部数据源和工具之间的无缝集成成为可能。无论你是构建 <code>AI</code> 驱动的  <code>IDE</code>、改善  <code>chat</code> 交互，还是构建自定义的  <code>AI</code> 工作流，<code>MCP</code> 提供了一种标准化的方式，将 <code>LLM</code> 与它们所需的上下文连接起来。</p><p>我经常使用的只有三个 <code>MCP</code></p><h3 id="deepwiki-mcp" tabindex="-1">deepwiki MCP <a class="header-anchor" href="#deepwiki-mcp" aria-label="Permalink to &quot;deepwiki MCP&quot;">​</a></h3><p><strong><code>deepwiki</code> 简介</strong></p><p><code>deepwiki</code> <code>MCP</code> 我们先放一边，先来了解下 <code>deepwiki</code>。</p><p><code>deepwiki</code> 是一个 <code>GitHub</code> 代码仓库智能 <code>AI</code> 阅读助手，这个工具可以自动将任何 <code>GitHub</code> 仓库转换为详细且易于阅读的知识库文档，并提供交互式图表和对话式 <code>AI</code> 助手，允许用户轻松理解仓库的技术细节、架构设计和使用方法。</p><p>它的网站为是<a href="https://deepwiki.com/" target="_blank" rel="noreferrer">https://deepwiki.com/</a></p><p>使用方法也很简单，直接在搜索栏搜索一个我们想要查找的 <code>github</code> 项目，比如我们想要查找 <code>vxe-table</code> 的文档：</p><p><a href="./images//deepwiki-search.png"></a></p><p>看下哪个是我们想要查找的库，通常看哪个星多就完了，一般都是第一个，点进去</p><p><a href="./images//deepwiki-detail.png"></a></p><p>可以看到，<code>deepwiki</code> 对 <code>vxe-table</code> 这个 <code>github</code> 项目进行了重新整理归纳，形成了一个包含简介、架构、构建与脚本、单文件组件、服务端渲染、集成与兼容的一个综合性知识库文档。文档中除了文字还包含大量的图表信息，如架构图、流程图等，我们可以清晰的了解项目的整体结构和状态流转。</p><p>到这里还没完，<code>deepwiki</code> 的一个很重要功能是，它可以通过内置的对话型 <code>AI</code> 助手，让用户可以自己与 <code>AI</code> 交互，去理解仓库的仓库的技术细节、架构设计或使用方法。比如，如果我想深入了解一下 vex-table 中，分页功能的具体实现细节，我们可以直接在网页下面的搜索工具里面输入：</p><p><a href="./images//deepwiki-AI-search.png"></a></p><p>就可以看到查询到的细节</p><p><a href="./images//deepwiki-AI-detail.png"></a></p><p>如果我们想继续提问，可以在底部对话框中继续输入问题，属实厉害！</p><p><strong><code>deepwiki</code> <code>MCP</code> 简介</strong></p><p>Devin 官方后来也推出了 <code>deepwiki</code> <code>MCP</code> 服务，这对某些开源项目的开发者来说可谓是一个重大利好，相当于免费拥有一个比官方文档更只能，更详细的项目文档。它可以从 <code>GitHub</code> 仓库或 <code>Deepwiki</code> 网站（deepwiki.com）获取最新的文档或代码库内容，通过 <code>MCP</code> 协议将爬取的内容转换为 <code>Markdown</code> 格式，供 <code>Cursor</code> 使用，特别适合需要查看 <code>GitHub</code> 仓库文档的场景。</p><p><code>DeepWiki</code> <code>MCP</code> 提供三种主要工具：</p><ul><li>read_wiki_structure：获取仓库文档的结构和主题</li><li>read_wiki_contents：获取仓库文档的详细内容</li><li>ask_question：对指定仓库提出问题，获取基于仓库文档和代码的 <code>AI</code> 回复</li></ul><p><strong>接入</strong></p><p>点开 <code>cursor</code> <code>AI</code> setting =&gt; Tools &amp; <code>MCP</code> =&gt; Add a Custom <code>MCP</code> Server ，添加如下：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;deepwiki&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://mcp.deepwiki.com/sse&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><strong>如何使用</strong></p><p>使用方法也很简单，直接在 <code>chat</code> 里加上 use <code>deepwiki</code> 和 你想查找的代码库这俩关键字就可以了 比如:</p><p><a href="./images//deepwiki-cursor-search.png"></a></p><p>它能够直接分析 vex-table 的官方文档中相关的文档和源码，对你的代码做出相应的更改，不用来回切换线上文档和编辑器，大幅度提高编码的准确性和效率。而且由于官方文档一直是最新的，能够有效避免 <code>AI</code> 幻觉问题（还是不能完全避免）。与之前我们通过@Docs 引入官方文档的做法，<code>Deepwiki</code> <code>MCP</code> 显然更方便和全面。</p><p><strong>使用场景</strong></p><p>我通常会在这几个方面使用它</p><ul><li>快速查询使用代码库文档/<code>API</code>。</li><li>针对解决开发过程中遇到的代码库/<code>npm</code> 包相关问题。</li><li>快速了解代码库的文档结构</li></ul><h3 id="context7" tabindex="-1">context7 <a class="header-anchor" href="#context7" aria-label="Permalink to &quot;context7&quot;">​</a></h3><p><strong>简介</strong></p><p><code>Context7</code> <code>MCP</code> 是 upstash 开发的 <code>MCP</code> 工具，它解决了 <code>AI</code> 知识过时的问题，这个工具能让 <code>AI</code> 获取最新、版本特定的文档和代码示例，从而让 <code>AI</code> 辅助编程时减少错误信息（幻觉）并提高效率。</p><p>官方网址：<a href="https://context7.com/%E3%80%82" target="_blank" rel="noreferrer">https://context7.com/。</a></p><p>它提供了两个工具：</p><ol><li>resolve_library_id: 根据提示词查找库名 ID。</li><li>get_library_docs: 根据库名 ID 获取库对应的文档内容。</li></ol><p><strong>接入</strong></p><p>点开 <code>cursor</code> <code>AI</code> setting =&gt; Tools &amp; <code>MCP</code> =&gt; Add a Custom <code>MCP</code> Server ，添加如下：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;context7&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://mcp.context7.com/mcp&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><strong>如何使用</strong></p><p>使用方法与 <code>deepwiki</code> 类似，直接在 <code>chat</code> 提示词中加上 <code>use context7</code> 关键字即可。<code>Context7</code> 会自动识别你提到的库或框架，并获取最新的文档和代码示例。</p><p>例如，当你想使用最新的 <code>React</code> 18 特性时，可以这样提问：</p><p>&quot;使用 <code>React</code> 18 的新特性创建一个组件，use <code>context7</code>&quot;</p><p>或者想了解某个库的最新 <code>API</code>：</p><p>&quot;如何使用 Next.js 15 的服务器组件？use <code>context7</code>&quot;</p><p><code>Context7</code> 会自动解析你的需求，查找相关的库文档，并获取最新版本的文档内容，确保生成的代码符合最新的 <code>API</code> 和最佳实践。</p><p><strong>使用场景</strong></p><p>我通常会在以下场景使用 <code>Context7</code>：</p><ul><li><strong>学习新框架或库</strong>：当需要学习新的框架、库或工具时，<code>Context7</code> 可以提供最新的官方文档和代码示例，帮助快速上手</li><li><strong>使用新版本特性</strong>：当框架或库发布了新版本，想使用新 <code>API</code> 或特性时，<code>Context7</code> 可以确保获取的是最新版本的文档，避免使用已废弃的 <code>API</code></li><li><strong>调试和问题排查</strong>：遇到问题时，<code>Context7</code> 可以获取最新的文档和示例，帮助理解正确的用法和最佳实践</li><li><strong>代码重构和优化</strong>：需要重构代码或优化实现时，<code>Context7</code> 可以提供当前版本的最佳实践和推荐模式</li></ul><p><strong><code>Deepwiki</code> 和 <code>Context7</code> 有什么区别</strong></p><p><code>Context7</code> 与 <code>Deepwiki</code> 很像 ，不过还是有点区别</p><ol><li>核心定位与目标 <code>Deepwiki</code> <code>MCP</code>：专注解析 <code>GitHub</code> 开源项目，生成结构化技术文档， 帮助快速理解项目架构与代码逻辑 <code>Context7</code> <code>MCP</code>：提供实时版本特定的文档和代码示例，解决 <code>AI</code> 知识过时和“幻觉”问题，确保代码符合最新版本的 <code>API</code> 规范</li><li>数据来源 <code>Deepwiki</code> <code>MCP</code>：主要从 <code>GitHub</code> 仓库获取信息，可能受仓库文档更新延迟影响，覆盖项目整体结构与代码逻辑 <code>Context7</code> <code>MCP</code>：直接从官方文档源获取数据，确保文档实时性与准确性，重点关注 <code>npm</code> 包和库的官方文档</li><li>功能特点 <code>Deepwiki</code> <code>MCP</code>：提供交互式架构图和流程图，支持对话式 <code>AI</code> 问答（针对项目），生成功能描述和技术栈分析，三种主要工具：read_wiki_structure（获取仓库文档结构和主题）、read_wiki_contents（获取文档详细内容）、ask_question（对指定仓库提问） <code>Context7</code> <code>MCP</code>：提供版本特定的文档，注入最新代码示例到 <code>AI</code> 上下文，两种主要工具：resolve_library_id（根据提示词查找库名 ID）、get_library_docs（根据库 ID 获取对应文档内容）</li><li>应用场景 <code>Deepwiki</code> <code>MCP</code>：快速理解新开源项目的整体结构，学习项目架构设计和技术栈选择，深入了解代码实现逻辑，评估和对比不同开源项目，查询 <code>GitHub</code> 仓库文档和 <code>API</code><code>Context7</code> <code>MCP</code>：学习新框架或库的最新用法，使用新版本特性和 <code>API</code>，获取最新的官方文档和最佳实践，调试时查找正确的 <code>API</code> 用法，确保代码与当前版本兼容</li><li>覆盖范围 <code>Deepwiki</code> <code>MCP</code>：覆盖整个 <code>GitHub</code> 项目（代码、文档、结构），适合需要全面了解项目的场景，支持大型项目的整体分析 <code>Context7</code> <code>MCP</code>：专注于库和框架的官方文档，更适合查询特定 <code>API</code> 和使用方法，主要关注文档文件，而非代码文件</li><li>时效性 <code>Deepwiki</code> <code>MCP</code>：依赖 <code>GitHub</code> 仓库的更新频率，可能存在信息滞后 <code>Context7</code> <code>MCP</code>：实时获取官方文档源数据，时效性更高</li></ol><p>根据我对这两个 <code>MCP</code> 的使用过程来看，如果单论防止 <code>AI</code> 幻觉，<code>Context7</code> 要比 <code>Deepwiki</code> 好点，而且 <code>Context7</code> 可以从不同版本解析代码库，但是如果要论项目的理解深度来说， <code>Deepwiki</code> 要比 <code>Context7</code> 好的多，因为 <code>Deepwiki</code> 是从代码 + 文档角度分析项目的，而 <code>Context7</code> 是从文档角度分析项目的。但是这俩 <code>MCP</code> 都有同一个缺点：搜索的库要么不全，要么特定版本没有。在 <code>Deepwiki</code> 中，一些冷门的库搜索不到， <code>context7</code> 中搜索库，版本可能又不全，比如搜索 <code>VXE-Table</code>，查到的版本只有两个： <a href="./images//context7-vexTable.png"></a> 遇见这种情况，要么等有人将库传到 <code>Deepwiki</code> 或者 <code>context7</code> 中，要么自己手动去传，我尝试了一下自己去传，速度还挺快的。</p><h3 id="mcp-feedback-enhanced" tabindex="-1">MCP-Feedback-Enhanced <a class="header-anchor" href="#mcp-feedback-enhanced" aria-label="Permalink to &quot;MCP-Feedback-Enhanced&quot;">​</a></h3><p><strong>简介</strong></p><p><code>MCP</code>-feedback-enhanced 是一个面向开发者的反馈驱动型工作流工具，核心目标是通过用户反馈优化 <code>AI</code> 操作，减少平台成本并提升开发效率。</p><p>地址：<a href="https://github.com/Minidoracat/mcp-feedback-enhanced" target="_blank" rel="noreferrer">https://github.com/Minidoracat/mcp-feedback-enhanced</a></p><p>直观的说就是，这个工具会让 <code>AI</code> 在完成阶段性任务后，不直接退出，而是先征求开发者意见，根据开发者的反馈，再决定退出还是继续一下步操作。当这个 <code>mcp</code> 被触发时，它会唤起一个基于 <code>Qt</code> <code>GUI</code> 开发的新界面，并提供更为丰富的反馈选项，具体有：</p><ul><li><code>AI</code> summary：先让 <code>AI</code> 梳理总结一下已经完成的工作，然后用户可以基于此给出反馈。</li><li>图像上传：支持 <code>PNG</code>/<code>JPG</code> 等多种格式，并且自动压缩至 1MB 以内，支持拖放和粘贴（<code>Ctrl</code>+V）。</li><li>多语言切换：英语、繁简中文，根据系统语言自动切换，支持界面内实时切换。</li></ul><p>他可以有效减少 token 的使用量</p><p><strong>接入</strong></p><p>点开 <code>cursor</code> <code>AI</code> setting =&gt; Tools &amp; <code>MCP</code> =&gt; Add a Custom <code>MCP</code> Server ，添加如下：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcp-feedback-enhanced&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;uvx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mcp-feedback-enhanced@latest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;timeout&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">600</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;autoApprove&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;interactive_feedback&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><strong>如何使用</strong></p><p>与前几个 <code>mcp</code> 一样，直接在 <code>chat</code> 里你的语句加入 use <code>mcp</code>-feedback-enhanced 就行了 比如： <a href="./images//mcpFeedBackEnhancedSearch.png"></a></p><p>允许 <code>mcp</code> 调用后，会打开一个 <code>GUI</code> 窗口，可以输入文字。</p><p><a href="./images//feedback.png"></a></p><p>比如我们可以输入：只查询 md 文档，</p><p><a href="./images//feedback2.png"></a></p><p>之后提交反馈，他会根据你的反馈再进行解答，解答完后会刷新这个窗口，我们可以再输入反馈，再获得解答....如此循环往复</p><p><a href="https://cursor.com/cn/docs/account/pricing" target="_blank" rel="noreferrer">https://cursor.com/cn/docs/account/pricing</a></p><p>注： <a href="https://cursor.com/cn/docs/account/pricing" target="_blank" rel="noreferrer">Cursor 的收费方式发生了更改</a>。如果按照之前的依据请求次数收费，我们可以通过调用 <code>mcp</code>-feedback-enhanced 压缩请求次数，通过不断询问用户是否问题已经解决，尽可能将所有更改压缩到一次请求中以减少请求次数。但是由于 <code>Cursor</code> 的收费方式变为现在请求额度收费（其实就是按照输入、输出总的 token 量收费），我们通过延长会话来减少计费次数的想法已经失效。 在新计费模式下，<code>mcp</code>-feedback-enhanced 的主要价值（节省费用）已失效，它现在最大的价值我认为应该是：通过交互反馈提高任务完成质量，减少返工，也可以通过这种方式确保 <code>AI</code> 理解需求后再继续，避免方向性错误。</p><p><strong>使用场景</strong></p><p>我通常会在以下场景中使用 <code>MCP</code>-Feedback-Enhanced</p><ol><li>复杂任务的分步确认</li><li>需求不明确时的迭代澄清</li><li>需要视觉参考的任务（需要大量上传图片、设计稿或者参考图例）</li><li>多伦迭代优化</li></ol><p>简而言之，复杂点的任务用它，简单明确的的任务不用它。</p>`,160);function h(u,b,k,m,g,C){const s=n("ArticleMetadata");return c(),o("div",null,[r,p(s),t])}const P=a(l,[["render",h]]);export{f as __pageData,P as default};
